Renderable: trait {
    render: fn(self) -> String,
}

Button: struct {
    label: String,
    impl Renderable {
        render: fn(self) -> String {
            return self.label
        }
    }
}

Panel: struct {
    title: String,
}

impl Panel.Renderable {
    render: fn(self) -> String {
        self.title
    }
}

run: fn() {
    b: Button{label: "ok"}
    print(b.render())
}

show: fn(panel: Panel) -> [Button] {
    [Button]{}
}
